g=[[8,8,1,1,1,1,1,1,8],[8,8,1,8,1,8,8,8,8],[8,8,8,8,1,8,8,8,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,8,8,8,1,8],[8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8]]
rows=[i for i,r in enumerate(g) if 1 in r]; cols=[j for j in range(9) if any(r[j]==1 for r in g)]
r0,r1_=min(rows),max(rows); c0,c1_=min(cols),max(cols)
out=[r[:] for r in g]
def fill(rs,cs):
    for r in rs:
        for c in cs:
            if out[r][c]==8: out[r][c]=2
fill(range(r0,r1_+1),[c0,c1_]); fill([r0,r1_],range(c0,c1_+1))
for r in range(r0+1,r1_):  # interior rows with horizontal run
    run=any(g[r][c]==1 and g[r][c+1]==1 for c in range(c0,c1_))
    if run: fill([r],range(c0,c1_+1))
for c in range(c0+1,c1_):
    if any(g[r][c]==1 and g[r+1][c]==1 for r in range(r0,r1_)): fill(range(r0,r1_+1),[c])
for r in out: print(r)
